#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

typedef long long ll;

typedef struct {
    ll a, b;
} Line;

typedef struct {
    ll a, b;
} Meal;

int cmp_line(const void *a, const void *b) {
    Line *x = (Line*)a;
    Line *y = (Line*)b;
    if (x->a != y->a) return (x->a < y->a) ? -1 : 1;
    return (x->b < y->b) ? -1 : (x->b > y->b) ? 1 : 0;
}

int cmp_meal(const void *a, const void *b) {
    Meal *x = (Meal*)a;
    Meal *y = (Meal*)b;
    if (x->a == 1 && y->a == 1) return 0;
    if (x->a == 1) return -1;
    if (y->a == 1) return 1;
    ll left = x->b * (y->a - 1);
    ll right = y->b * (x->a - 1);
    if (left > right) return -1;
    if (left < right) return 1;
    return 0;
}

ll mod_pow(ll base, ll exp) {
    ll res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

ll mod_inv(ll x) {
    return mod_pow(x, MOD - 2);
}

int main() {
    int N, M;
    ll K;
    scanf("%d %d %lld", &N, &M, &K);

