    Meal *meals = malloc(M * sizeof(Meal));
    for (int i = 0; i < M; i++) {
        meals[i].a = a_meal[i];
        meals[i].b = b_meal[i];
    }
    qsort(meals, M, sizeof(Meal), cmp_meal);

    ll A_m = 1, B_m = 0;
    for (int i = 0; i < M; i++) {
        A_m = (A_m * meals[i].a) % MOD;
        B_m = (B_m * meals[i].a + meals[i].b) % MOD;
    }

    // Process spells
    Line *lines = malloc(N * sizeof(Line));
    for (int i = 0; i < N; i++) {
        lines[i].a = a_spell[i];
        lines[i].b = b_spell[i];
    }
    qsort(lines, N, sizeof(Line), cmp_line);

