                ll term = (powA * y_mod) % MOD;
                ll geom = (powA - 1 + MOD) % MOD;
                geom = (geom * inv) % MOD;
                geom = (geom * (B % MOD)) % MOD;
                final_spell_mod = (term + geom) % MOD;
            }
